import { cn } from "@/lib/utils";

/**
 * Theme-aware flat vector illustration.
 * Light variant lives at /illustrations/<name>.svg, dark variant at
 * /illustrations/dark/<name>.svg. Both are generated by
 * scripts/gen-illustrations.mjs.
 */
export function Illustration({
  name,
  alt,
  className,
  imgClassName,
  loading = "lazy",
}: {
  name: string;
  alt: string;
  className?: string;
  imgClassName?: string;
  loading?: "lazy" | "eager";
}) {
  return (
    <span className={cn("block", className)}>
      <img
        src={`/illustrations/${name}.svg`}
        alt={alt}
        loading={loading}
        className={cn("h-auto w-full dark:hidden", imgClassName)}
      />
      <img
        src={`/illustrations/dark/${name}.svg`}
        alt=""
        aria-hidden="true"
        loading={loading}
        className={cn("h-auto w-full hidden dark:block", imgClassName)}
      />
    </span>
  );
}
